/* From Uiverse.io by 3bdel3ziz-T  - Tags: red, blue, social, smooth, radio, custom, click effect, click animation */
.__UIV_SCOPE__ .container {
  --col-gray: #3f3f3f;
  --col-white: #fff;
  --col-like: #2196f3;
  --col-dislike: #ff3232;
  --transition: 350ms;
  background-color: var(--col-gray);
  width: 130px;
  border-radius: 50px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px;
  user-select: none;
  /*you can easlly change the number by using this variabels*/
  --zero: translateY(calc(50% - 11px));
  --one: translateY(calc(40% - 11px));
  --two: translateY(calc(30% - 11px));
  --three: translateY(calc(20% - 11px));
  --four: translateY(calc(10% - 11px));
  --five: translateY(calc(0% - 11px));
  --six: translateY(calc(-10% - 11px));
  --seven: translateY(calc(-20% - 11px));
  --eight: translateY(calc(-30% - 11px));
  --nine: translateY(calc(-40% - 11px));
  --ten: translateY(calc(-50% - 11px));
}
.__UIV_SCOPE__ .container:has(#like:checked) .count {
  border-left-color: var(--col-like);
  border-right-color: transparent;
}
.__UIV_SCOPE__ .container:has(#like:checked) .count .number:first-child {
  /*change first number from here*/
  /*when click on like*/
  transform: var(--nine);
}
.__UIV_SCOPE__ .container:has(#like:checked) .count .number:nth-child(2) {
  /*change second number from here*/
  /*when click on like*/
  transform: var(--five);
}
.__UIV_SCOPE__ .container:has(#like:checked) .count .number:last-child {
  /*change third number from here*/
  /*when click on like*/
  transform: var(--three);
}
.__UIV_SCOPE__ .container:has(#dislike:checked) > .count {
  border-right-color: var(--col-dislike);
  border-left-color: transparent;
}
.__UIV_SCOPE__ .container:has(#dislike:checked) > .count .number:first-child {
  /*change first number from here*/
  /*when click on dislike*/
  transform: var(--zero);
}
.__UIV_SCOPE__ .container:has(#dislike:checked) > .count .number:nth-child(2) {
  /*change second number from here*/
  /*when click on dislike*/
  transform: var(--zero);
}
.__UIV_SCOPE__ .container:has(#dislike:checked) > .count .number:last-child {
  /*change third number from here*/
  /*when click on dislike*/
  transform: var(--nine);
}
.__UIV_SCOPE__ .container label input {
  display: none;
}
.__UIV_SCOPE__ .container #like:checked + svg {
  animation: evaluation-animation var(--transition) ease-in-out 0s 1 normal both;
  fill: var(--col-like);
}
.__UIV_SCOPE__ .container #dislike:checked + svg {
  animation: evaluation-animation var(--transition) ease-in-out 0s 1 normal both;
  fill: var(--col-dislike);
}
.__UIV_SCOPE__ .container .icon {
  cursor: pointer;
  fill: var(--col-white);
  height: 24px;
  width: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .container .icon.like {
  margin-left: 9px;
}
.__UIV_SCOPE__ .container .icon.dislike {
  margin-right: 9px;
}
.__UIV_SCOPE__ .container .count {
  transition: var(--transition);
  flex: 1;
  border-left: 1px solid var(--col-white);
  border-right: 1px solid var(--col-white);
  position: relative;
  height: 24px;
  overflow: hidden;
  margin: auto;
  color: white;
  font-size: 16px;
  font-family: sans-serif;
  display: flex;
  align-items: center;

  justify-content: center;
  gap: 0.5px;
  flex-direction: row;
}
.__UIV_SCOPE__ .container .count .number {
  display: flex;
  flex-direction: column;
  transform: translateY(calc(50% - 8px));
  transition: 1000ms cubic-bezier(0.68, -0.55, 0.27, 1.55);
}
.__UIV_SCOPE__ .container .count .number:first-child {
  transition-delay: 200ms;
}
.__UIV_SCOPE__ .container .count .number:nth-child(2) {
  transition-delay: 150ms;
}
.__UIV_SCOPE__ .container .count .number:last-child {
  transition-delay: 50ms;
}

@keyframes evaluation-animation {
  0%,
  100% {
    transform: scale(1) rotate(0deg);
  }
  50% {
    transform: scale(1.1) rotate(-10deg);
  }
}
